const tmjlite = require('tmjlite');

const db = tmjlite.connectShared('app.tmjp');   // thread-safe, MVCC
const st = db.prepare('INSERT INTO rs (ns, k, samples) VALUES (?, ?, ?) ' +
                      'ON CONFLICT (ns, k) DO UPDATE SET samples = excluded.samples;');
db.begin();                                      // um commit para o lote
for (const it of lote) st.execute([it.ns, it.k, it.samples]);
db.commit();
const cur = db.cursor('SELECT samples FROM rs WHERE ns = ?', ['ns3']);
let total = 0;
for (const row of cur) total += row.samples;     // streaming: memória O(1 linha)
cur.close();

