using var db = TMJLite.ConnectShared("app.tmjp");   // thread-safe, MVCC
using var st = db.Prepare("INSERT INTO rs (ns, k, samples) VALUES (?, ?, ?) " +
                          "ON CONFLICT (ns, k) DO UPDATE SET samples = excluded.samples;");
db.Transaction(() => { foreach (var it in lote) st.Execute(it.Ns, it.K, it.Samples); });
using var cur = db.Cursor("SELECT samples FROM rs WHERE ns = ?", "ns3");
long total = 0;
foreach (var row in cur) total += row.GetInt("samples");   // streaming: O(1 linha)

try (SharedConnection db = TMJLite.connectShared("app.tmjp");   // thread-safe, MVCC
     PreparedStatement st = db.prepare(
         "INSERT INTO rs (ns, k, samples) VALUES (?, ?, ?) ON CONFLICT (ns, k) DO UPDATE SET samples = excluded.samples;")) {
    db.begin();                                   // um commit para o lote
    for (Item it : lote) st.execute(it.ns, it.k, it.samples);
    db.commit();
    try (Cursor cur = db.cursor("SELECT samples FROM rs WHERE ns = ?", "ns3")) {
        for (Row row : cur) total += row.getInt("samples");   // streaming: O(1 linha)
    }
}

use tmjlite_rs::{SharedConnection, Value};

let db = SharedConnection::open("app.tmjp")?;    // thread-safe, MVCC
let st = db.prepare("INSERT INTO rs (ns, k, samples) VALUES (?, ?, ?) ON CONFLICT (ns, k) DO UPDATE SET samples = excluded.samples;")?;
db.transaction(|db| {                             // um commit para o lote
    for it in &lote { db.execute_prepared(&st, &[Value::Text(it.ns.clone()), Value::Text(it.k.clone()), Value::Int(it.samples)])?; }
    Ok(())
})?;
let total = db.cursor("SELECT samples FROM rs WHERE ns = 'ns3';")?
    .fold(0i64, |t, row| Ok(t + row.get_int(0).unwrap_or(0)))?;   // streaming: O(1 linha)
